package main
import("debug/elf";"debug/gosym";"fmt";"os";"strings")
func main(){for _,p:=range os.Args[1:] {f,e:=elf.Open(p);if e!=nil{panic(e)};s:=f.Section(".gopclntab");if s==nil{panic("no pclntab")};b,e:=s.Data();if e!=nil{panic(e)};tab,e:=gosym.NewTable(nil,gosym.NewLineTable(b,f.Section(".text").Addr));if e!=nil{panic(e)}; runtime,options,rekor,verify:=0,0,0,0;for _,fn:=range tab.Funcs{if strings.Contains(fn.Name,"grpc-gateway/v2/runtime."){runtime++};if strings.Contains(fn.Name,"grpc-gateway/v2/protoc-gen-openapiv2/options."){options++};if strings.Contains(fn.Name,"rekor-tiles/v2/"){rekor++};if strings.Contains(fn.Name,"sigstore-go/pkg/verify."){verify++}};fmt.Printf("%s functions=%d gateway_runtime=%d gateway_options=%d rekor=%d sigstore_verify=%d\n",p,len(tab.Funcs),runtime,options,rekor,verify);f.Close()}}
